# Filter to counted rows only
df_counted = df[df['row_kind'] == 'counted'].copy()

# Parse dates
df_counted['Admit Date'] = pd.to_datetime(df_counted['Admit Date'], errors='coerce')
df_counted['Discharge Date'] = pd.to_datetime(df_counted['Discharge Date'], errors='coerce')

# Compute LOS
df_counted['LOS'] = (df_counted['Discharge Date'] - df_counted['Admit Date']).dt.days

# Inpatient filter
ip_mask = df_counted['Encounter Type'].str.lower().str.strip().isin(['inpatient', 'ip', 'inpt', 'i'])
df_ip = df_counted[ip_mask & df_counted['Discharge Date'].notna()].copy()

# EDA
try:
    eda_cols = ['Total Charges', 'LOS']
    for col in eda_cols:
        if col in df_counted.columns:
            s = df_counted[col].dropna()
            result['eda_summary'][col] = {
                'mean': float(s.mean()), 'std': float(s.std()),
                'min': float(s.min()), 'max': float(s.max()),
                'median': float(s.median()), 'count': int(s.count())
            }
except Exception:
    pass

# Segmentation
try:
    seg_cols = ['Encounter Type', 'Department', 'Discharge Disposition']
    metric = 'Total Charges'
    for sc in seg_cols:
        if sc not in df_counted.columns:
            continue
        grp = df_counted.groupby(sc)[metric].mean().nlargest(10)
        result['segments'].append({
            'segment_column': sc, 'metric_column': metric,
            'aggregation': 'mean', 'label': None,
            'results': [{'name': str(k), 'value': float(v)} for k, v in grp.items()]
        })
    # Count by Encounter Type
    for sc in seg_cols:
        if sc not in df_counted.columns:
            continue
        grp = df_counted.groupby(sc)[metric].count().nlargest(10)
        result['segments'].append({
            'segment_column': sc, 'metric_column': metric,
            'aggregation': 'count', 'label': None,
            'results': [{'name': str(k), 'value': float(v)} for k, v in grp.items()]
        })
    # ALOS by Department
    if len(df_ip) >= 30:
        alos_grp = df_ip.groupby('Department').apply(
            lambda x: x['LOS'].sum() / x['Discharge Date'].notna().sum()
        ).nlargest(10)
        result['segments'].append({
            'segment_column': 'Department', 'metric_column': 'LOS',
            'aggregation': 'mean', 'label': 'alos_by_department',
            'results': [{'name': str(k), 'value': float(v)} for k, v in alos_grp.items()]
        })
    # Readmission rate overall
    excl_disp = {20, 7, 2, 5, 43, 66, 82, 85, 88, 93, 94}
    if len(df_ip) >= 30:
        df_ip2 = df_ip.copy()
        df_ip2['Discharge Disposition Num'] = pd.to_numeric(df_ip2['Discharge Disposition'], errors='coerce')
        last_admit = df_ip2['Admit Date'].max()
        cutoff = last_admit - pd.Timedelta(days=30)
        eligible = df_ip2[
            (df_ip2['Discharge Date'] <= cutoff) &
            (~df_ip2['Discharge Disposition Num'].isin(excl_disp))
        ].copy()
        readmit_count = 0
        for _, row in eligible.iterrows():
            same_pt = df_ip2[
                (df_ip2['MRN'] == row['MRN']) &
                (df_ip2['Admit Date'] > row['Discharge Date']) &
                (df_ip2['Admit Date'] <= row['Discharge Date'] + pd.Timedelta(days=30))
            ]
            if len(same_pt) > 0:
                readmit_count += 1
        denom = len(eligible)
        rate = readmit_count / denom if denom > 0 else float('nan')
        result['segments'].append({
            'segment_column': 'Encounter Type', 'metric_column': 'Discharge Date',
            'aggregation': 'ratio', 'label': 'readmission_rate',
            'results': [{'name': 'Inpatient', 'value': float(rate)}]
        })
    # Mortality rate
    if len(df_ip) >= 30:
        df_ip3 = df_ip.copy()
        df_ip3['Discharge Disposition Num'] = pd.to_numeric(df_ip3['Discharge Disposition'], errors='coerce')
        mort_mask = df_ip3['Discharge Disposition Num'] == 20
        discharges = df_ip3['Encounter ID'].nunique()
        mort = df_ip3[mort_mask]['Encounter ID'].nunique()
        mort_rate = mort / discharges if discharges > 0 else float('nan')
        result['segments'].append({
            'segment_column': 'Encounter Type', 'metric_column': 'Encounter ID',
            'aggregation': 'ratio', 'label': 'mortality_rate',
            'results': [{'name': 'Inpatient', 'value': float(mort_rate)}]
        })
except Exception:
    pass

# Correlations
try:
    num_df = df_counted[['Total Charges', 'LOS']].dropna()
    if len(num_df) >= 30:
        r = float(num_df['Total Charges'].corr(num_df['LOS']))
        if abs(r) >= 0.2:
            result['correlations']['Total Charges__LOS'] = r
except Exception:
    pass

# Anomalies
try:
    anom_cols = ['Total Charges', 'LOS']
    total_flagged = 0
    for col in anom_cols:
        if col not in df_counted.columns:
            continue
        s = df_counted[col].dropna()
        if s.nunique() < 5 or total_flagged >= 25:
            continue
        skew = float(s.skew())
        shift = max(0, -s.min())
        s_t = np.log1p(s + shift) if abs(skew) > 2 else s
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        flagged = s_t[(s_t < lo3) | (s_t > hi3)]
        pct = len(flagged) / len(s)
        if pct > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'{float(np.expm1(hi3) - shift):.2f} max' if abs(skew) > 2 else f'{float(hi3):.2f} max',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; {pct*100:.1f}% of values exceed the 3×IQR boundary — column not individually flagged'
            })
            continue
        for idx in flagged.index:
            if total_flagged >= 25:
                break
            orig_val = float(df_counted.loc[idx, col])
            st_val = float(s_t[idx])
            if st_val > hi5 or st_val < lo5:
                sev = 'critical'
            elif st_val > hi4 or st_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            if abs(skew) > 2:
                lo_orig = float(np.expm1(lo3) - shift)
                hi_orig = float(np.expm1(hi3) - shift)
            else:
                lo_orig, hi_orig = float(lo3), float(hi3)
            exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val:.2f} lies outside expected range {exp_range}'
            })
            total_flagged += 1
except Exception:
    pass

# Trends (non-MoM — MoM computed externally; do 7d rolling for Total Charges)
try:
    df_counted['Discharge Date'] = pd.to_datetime(df_counted['Discharge Date'], errors='coerce')
    ts = df_counted.dropna(subset=['Discharge Date']).set_index('Discharge Date').sort_index()
    roll = ts['Total Charges'].resample('7D').mean().dropna()
    if len(roll) >= 4:
        first_h = roll.iloc[:len(roll)//2].mean()
        second_h = roll.iloc[len(roll)//2:].mean()
        pct = float((second_h - first_h) / first_h * 100) if first_h != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': 'Total Charges', 'period': '7d_rolling',
            'direction': direction, 'pct_change': round(pct, 2), 'segment': None
        })
except Exception:
    pass

# Forecasting (simple linear extrapolation on monthly Total Charges)
try:
    df_counted['Discharge Date'] = pd.to_datetime(df_counted['Discharge Date'], errors='coerce')
    monthly = df_counted.dropna(subset=['Discharge Date']).set_index('Discharge Date')['Total Charges'].resample('ME').mean().dropna()
    if len(monthly) >= 3:
        x = np.arange(len(monthly))
        y = monthly.values
        slope, intercept = float(np.polyfit(x, y, 1))
        next_periods = 3
        for i in range(1, next_periods + 1):
            pred_val = intercept + slope * (len(monthly) - 1 + i)
            last_date = monthly.index[-1]
            fwd = last_date + pd.DateOffset(months=i)
            result['forecast_points'].append({
                'period': fwd.strftime('%Y-%m'), 'value': round(float(pred_val), 2)
            })
except Exception:
    pass

result['assumptions'] = [
    "Only 'counted' rows used for all figures; test/voided/superseded rows excluded.",
    "LOS computed as Discharge Date minus Admit Date in days; same-day = 0.",
    "Readmission rate excludes discharges in last 30 days of data and excludes expired/AMA/transferred dispositions.",
    "Mortality rate uses disposition code 20 (expired) only.",
    "Forecast is a 3-month linear extrapolation on monthly mean Total Charges — indicative only."
]
